}

// C# pattern for Object destructuring, defaults, and renaming
public sealed record Config(int Retries, string Endpoint);

public async Task<JsonDocument> CallAsync(Config cfg, string path) {
    for (var i = 0; i < cfg.Retries; i++) {
        var res = await _http.GetAsync(cfg.Endpoint + path);
        if (res.IsSuccessStatusCode) return await JsonDocument.ParseAsync(await res.Content.ReadAsStreamAsync());
    }
    throw new InvalidOperationException("exhausted retries");
}

function diagnose(error) {
  if (error instanceof Error) return error.message;
  if (typeof error === 'string') return error;
  return 'unknown failure';
}
